-- 019: researched school data (official sources, collected 2026-11-16). Seeded into each user's own rows, always unverified.
create table if not exists public.school_reference_data (
  school_name text not null, field text not null, value_num numeric, value_text text, currency text,
  source_name text not null, source_url text not null, date_accessed date not null default date '2026-11-16', publication_year int,
  primary key (school_name, field)
);
alter table public.school_reference_data enable row level security;
drop policy if exists "reference read" on public.school_reference_data;
create policy "reference read" on public.school_reference_data for select to authenticated using (true);
truncate public.school_reference_data;

-- seeding must not hand out XP
create or replace function public.xp_school_data() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if coalesce(current_setting('app.seeding', true), '') = '1' then return new; end if;
  if btrim(coalesce(new.source_name, '')) <> '' and btrim(coalesce(new.source_url, '')) <> '' then
    perform public.award_xp(new.user_id, 'sourced_data_point', 5, 'school_admissions_data', new.id, 20);
  end if;
  return new;
end $$;

create or replace function public.seed_my_school_data() returns int language plpgsql security invoker set search_path = public as $$
declare n int;
begin
  perform set_config('app.seeding', '1', true);
  select s.id, d.field, d.value_num, d.value_text, d.currency, d.source_name, d.source_url, d.date_accessed, d.publication_year, 'unverified'
  from public.school_reference_data d join public.schools s on s.name = d.school_name and s.user_id = auth.uid() and s.deleted_at is null
  on conflict (school_id, field) do nothing;
  get diagnostics n = row_count;
  perform set_config('app.seeding', '', true);
  return n;
end $$;

-- first-run seeding now fills the research data as well
create or replace function public.seed_my_schools() returns int language plpgsql security invoker set search_path = public as $$
declare n int;
begin
  select s.name, s.short, s.country, s.loc from (values
    ('Harvard Business School','HBS','United States','Boston, MA'),('Stanford GSB','GSB','United States','Stanford, CA'),
    ('Wharton','Wharton','United States','Philadelphia, PA'),('Chicago Booth','Booth','United States','Chicago, IL'),
    ('MIT Sloan','Sloan','United States','Cambridge, MA'),('Kellogg','Kellogg','United States','Evanston, IL'),
    ('Columbia Business School','CBS','United States','New York, NY'),('Berkeley Haas','Haas','United States','Berkeley, CA'),
    ('Yale SOM','SOM','United States','New Haven, CT'),('Dartmouth Tuck','Tuck','United States','Hanover, NH'),
    ('Michigan Ross','Ross','United States','Ann Arbor, MI'),('NYU Stern','Stern','United States','New York, NY'),
    ('UCLA Anderson','Anderson','United States','Los Angeles, CA'),('Cornell Johnson','Johnson','United States','Ithaca, NY'),
    ('Duke Fuqua','Fuqua','United States','Durham, NC'),('UVA Darden','Darden','United States','Charlottesville, VA'),
    ('INSEAD','INSEAD','France','Fontainebleau'),('London Business School','LBS','United Kingdom','London'),
    ('HEC Paris','HEC','France','Jouy-en-Josas'),('Cambridge Judge','Judge','United Kingdom','Cambridge'),
    ('Oxford Saïd','Saïd','United Kingdom','Oxford'),('IESE','IESE','Spain','Barcelona'),('IMD','IMD','Switzerland','Lausanne'),
    ('NUS','NUS','Singapore','Singapore'),('HKUST','HKUST','Hong Kong','Hong Kong'),('CEIBS','CEIBS','China','Shanghai')
  ) as s(name, short, country, loc)
  where not exists (select 1 from public.schools x where x.user_id = auth.uid() and x.name = s.name);
  get diagnostics n = row_count;
  perform public.seed_my_school_data();
  return n;
end $$;

-- source label corrections found in the accuracy check
update public.school_reference_data set source_name = 'Chicago Booth Full-Time MBA Cost 2026-27 (full program tuition, billed in six quarterly installments over nine months; applies to 2026-27 only)' where school_name = 'Chicago Booth' and field = 'tuition';
update public.school_reference_data set source_name = 'UCLA Anderson FT MBA estimated costs, AY 2026-27 (listed as MBA program fees, one academic year; excludes other mandatory UCLA fees and health insurance)' where school_name = 'UCLA Anderson' and field = 'tuition';
